import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor bn2d_forward(torch::Tensor x,
                            torch::Tensor weight,
                            torch::Tensor bias,
                            torch::Tensor running_mean,
                            torch::Tensor running_var,
                            bool training,
                            double momentum,
                            double eps);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

// ---------------------------------------------------------------------
// Kernel 1: reduce sum and sum-of-squares per channel over (N, H, W)
// ---------------------------------------------------------------------
__global__ void bn_reduce_kernel(
    const float* __restrict__ X,
    double* __restrict__ sum,
    double* __restrict__ sumsq,
    int N, int C, int H, int W)
{
    int c = blockIdx.y;
    long HW = (long)H * W;
    long count = (long)N * HW;

    long tid    = (long)blockIdx.x * blockDim.x + threadIdx.x;
    long stride = (long)gridDim.x * blockDim.x;

    double local_sum   = 0.0;
    double local_sumsq = 0.0;

    for (long idx = tid; idx < count; idx += stride) {
        long n  = idx / HW;
        long hw = idx % HW;
        long offset = (n * C + c) * HW + hw;
        float v = X[offset];
        local_sum   += (double)v;
        local_sumsq += (double)v * (double)v;
    }

    extern __shared__ double smem[];
    double* s_sum   = smem;
    double* s_sumsq = smem + blockDim.x;

    int t = threadIdx.x;
    s_sum[t]   = local_sum;
    s_sumsq[t] = local_sumsq;
    __syncthreads();

    for (int s = blockDim.x >> 1; s > 0; s >>= 1) {
        if (t < s) {
            s_sum[t]   += s_sum[t + s];
            s_sumsq[t] += s_sumsq[t + s];
        }
        __syncthreads();
    }

    if (t == 0) {
        atomicAdd(&sum[c],   s_sum[0]);
        atomicAdd(&sumsq[c], s_sumsq[0]);
    }
}

// ---------------------------------------------------------------------
// Kernel 2: finalize per-channel mean/invstd, update running stats
// ---------------------------------------------------------------------
__global__ void bn_finalize_kernel(
    const double* __restrict__ sum,
    const double* __restrict__ sumsq,
    float* __restrict__ mean_out,
    float* __restrict__ invstd_out,
    float* __restrict__ running_mean,
    float* __restrict__ running_var,
    int C, long count, float eps, float momentum, bool training)
{
    int c = blockIdx.x * blockDim.x + threadIdx.x;
    if (c >= C) return;

    if (training) {
        double m   = sum[c] / (double)count;
        double var = sumsq[c] / (double)count - m * m;
        if (var < 0.0) var = 0.0;

        mean_out[c]   = (float)m;
        invstd_out[c] = rsqrtf((float)var + eps);

        double unbiased_var = (count > 1) ? var * (double)count / (double)(count - 1) : var;

        running_mean[c] = (1.0f - momentum) * running_mean[c] + momentum * (float)m;
        running_var[c]  = (1.0f - momentum) * running_var[c]  + momentum * (float)unbiased_var;
    } else {
        mean_out[c]   = running_mean[c];
        invstd_out[c] = rsqrtf(running_var[c] + eps);
    }
}

// ---------------------------------------------------------------------
// Kernel 3: apply normalization using CUTE tensors
// ---------------------------------------------------------------------
__global__ void bn_apply_kernel(
    const float* __restrict__ X,
    float* __restrict__ Y,
    const float* __restrict__ mean,
    const float* __restrict__ invstd,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    int N, int C, int H, int W)
{
    constexpr int Threads = 256;
    constexpr int Vec = 4;

    int n = blockIdx.z;
    int c = blockIdx.y;
    long HW = (long)H * W;
    long tile = (long)Threads * Vec;
    long base = (long)blockIdx.x * tile;

    const float* Xp = X + ((long)n * C + c) * HW;
    float* Yp = Y + ((long)n * C + c) * HW;

    // CUTE tensors over the contiguous (H*W) slice for this (n, c)
    auto mX = make_tensor(make_gmem_ptr(Xp), make_shape(HW), make_stride(Int<1>{}));
    auto mY = make_tensor(make_gmem_ptr(Yp), make_shape(HW), make_stride(Int<1>{}));

    float m  = mean[c];
    float is = invstd[c];
    float w  = weight ? weight[c] : 1.0f;
    float b  = bias   ? bias[c]   : 0.0f;

    float scale = is * w;
    float shift = b - m * scale;

    #pragma unroll
    for (int i = 0; i < Vec; ++i) {
        long idx = base + threadIdx.x + (long)i * Threads;
        if (idx < HW) {
            float v = mX(idx);
            mY(idx) = v * scale + shift;
        }
    }
}

// ---------------------------------------------------------------------
// Host wrapper
// ---------------------------------------------------------------------
torch::Tensor bn2d_forward(torch::Tensor x,
                            torch::Tensor weight,
                            torch::Tensor bias,
                            torch::Tensor running_mean,
                            torch::Tensor running_var,
                            bool training,
                            double momentum,
                            double eps) {
    TORCH_CHECK(x.is_cuda(), "x must be CUDA");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
    TORCH_CHECK(x.dim() == 4, "x must be 4D (N,C,H,W)");

    auto x_c = x.contiguous();
    auto weight_c = weight.contiguous();
    auto bias_c = bias.contiguous();
    auto running_mean_c = running_mean.contiguous();
    auto running_var_c = running_var.contiguous();

    int N = (int)x_c.size(0);
    int C = (int)x_c.size(1);
    int H = (int)x_c.size(2);
    int W = (int)x_c.size(3);

    auto y = torch::empty_like(x_c);

    auto opts_double = x_c.options().dtype(at::kDouble);
    auto opts_float  = x_c.options().dtype(at::kFloat);

    auto sum   = torch::zeros({C}, opts_double);
    auto sumsq = torch::zeros({C}, opts_double);
    auto mean_buf   = torch::empty({C}, opts_float);
    auto invstd_buf = torch::empty({C}, opts_float);

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    long count = (long)N * H * W;

    if (training) {
        constexpr int Threads = 256;
        long HW = (long)H * W;
        long total = (long)N * HW;
        int blocks_per_channel = (int)((total + Threads - 1) / Threads);
        blocks_per_channel = std::min(blocks_per_channel, 4096);
        blocks_per_channel = std::max(blocks_per_channel, 1);

        dim3 grid(blocks_per_channel, C);
        dim3 block(Threads);
        size_t shmem = 2 * Threads * sizeof(double);

        bn_reduce_kernel<<<grid, block, shmem, stream>>>(
            x_c.data_ptr<float>(),
            sum.data_ptr<double>(),
            sumsq.data_ptr<double>(),
            N, C, H, W
        );
        auto err = cudaGetLastError();
        TORCH_CHECK(err == cudaSuccess, "bn_reduce_kernel launch failed: ", cudaGetErrorString(err));
    }

    {
        int threads = 128;
        int blocks = (C + threads - 1) / threads;
        bn_finalize_kernel<<<blocks, threads, 0, stream>>>(
            sum.data_ptr<double>(),
            sumsq.data_ptr<double>(),
            mean_buf.data_ptr<float>(),
            invstd_buf.data_ptr<float>(),
            running_mean_c.data_ptr<float>(),
            running_var_c.data_ptr<float>(),
            C, count, (float)eps, (float)momentum, training
        );
        auto err = cudaGetLastError();
        TORCH_CHECK(err == cudaSuccess, "bn_finalize_kernel launch failed: ", cudaGetErrorString(err));
    }

    {
        constexpr int Threads = 256;
        constexpr int Vec = 4;
        long HW = (long)H * W;
        long tile = (long)Threads * Vec;
        int gx = (int)((HW + tile - 1) / tile);

        dim3 grid(gx, C, N);
        dim3 block(Threads);

        bn_apply_kernel<<<grid, block, 0, stream>>>(
            x_c.data_ptr<float>(),
            y.data_ptr<float>(),
            mean_buf.data_ptr<float>(),
            invstd_buf.data_ptr<float>(),
            weight_c.data_ptr<float>(),
            bias_c.data_ptr<float>(),
            N, C, H, W
        );
        auto err = cudaGetLastError();
        TORCH_CHECK(err == cudaSuccess, "bn_apply_kernel launch failed: ", cudaGetErrorString(err));
    }

    // Copy back updated running stats (in-place update of the passed tensors)
    running_mean.copy_(running_mean_c);
    running_var.copy_(running_var_c);

    return y;
}
"""

bn2d_ext = load_inline(
    name="cute_bn2d_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["bn2d_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/root/cutegen_test/cutegen/cutlass/include",
        "/root/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Custom CUTE/CUDA implementation of BatchNorm2d.
    """
    def __init__(self, num_features: int):
        super(ModelNew, self).__init__()
        self.num_features = num_features
        self.eps = 1e-5
        self.momentum = 0.1

        self.weight = nn.Parameter(torch.ones(num_features))
        self.bias = nn.Parameter(torch.zeros(num_features))

        self.register_buffer("running_mean", torch.zeros(num_features))
        self.register_buffer("running_var", torch.ones(num_features))
        self.register_buffer("num_batches_tracked", torch.tensor(0, dtype=torch.long))

        self._ext = bn2d_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if self.training:
            self.num_batches_tracked += 1

        return self._ext.bn2d_forward(
            x,
            self.weight,
            self.bias,
            self.running_mean,
            self.running_var,
            self.training,
            float(self.momentum),
            float(self.eps),
        )

