import torch
import torch.nn as nn

from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

# ---------------------------------------------------------------------------
# Hand-authored PTX implementing BatchNorm2d forward (training + eval) using
# three kernels:
#   1. bn_reduce_kernel   -> per-channel sum / sum-of-squares over (N,H,W)
#   2. bn_finalize_kernel -> per-channel mean/invstd + running stats update
#   3. bn_apply_kernel    -> normalize + affine transform
# ---------------------------------------------------------------------------
PTX_SOURCE = r"""
.version 8.7
.target sm_89
.address_size 64

.extern .shared .align 8 .b8 smem[];

//
// Kernel 1: reduce sum and sum-of-squares per channel over (N, H, W)
//
.visible .entry bn_reduce_kernel(
    .param .u64 X,
    .param .u64 sum,
    .param .u64 sumsq,
    .param .u32 N,
    .param .u32 C,
    .param .u32 H,
    .param .u32 W
)
{
    .reg .pred %p<6>;
    .reg .u32 %r<22>;
    .reg .u64 %rd<35>;
    .reg .f32 %f<4>;
    .reg .f64 %fd<16>;

    ld.param.u64 %rd1, [X];
    ld.param.u64 %rd2, [sum];
    ld.param.u64 %rd3, [sumsq];
    ld.param.u32 %r1, [N];
    ld.param.u32 %r2, [C];
    ld.param.u32 %r3, [H];
    ld.param.u32 %r4, [W];

    cvta.to.global.u64 %rd4, %rd1;
    cvta.to.global.u64 %rd5, %rd2;
    cvta.to.global.u64 %rd6, %rd3;

    mov.u32 %r5, %ctaid.y;      // c
    mov.u32 %r6, %ctaid.x;      // bx
    mov.u32 %r7, %ntid.x;       // threads
    mov.u32 %r8, %tid.x;        // tid
    mov.u32 %r9, %nctaid.x;     // grid.x

    cvt.u64.u32 %rd7, %r3;      // H
    cvt.u64.u32 %rd8, %r4;      // W
    mul.lo.u64 %rd9, %rd7, %rd8;    // HW

    cvt.u64.u32 %rd10, %r1;     // N
    mul.lo.u64 %rd11, %rd10, %rd9;  // count

    cvt.u64.u32 %rd12, %r9;     // nctaid
    cvt.u64.u32 %rd13, %r7;     // ntid
    mul.lo.u64 %rd14, %rd12, %rd13; // stride

    cvt.u64.u32 %rd15, %r6;     // bx
    mul.lo.u64 %rd16, %rd15, %rd13; // bx*ntid
    cvt.u64.u32 %rd17, %r8;     // tid
    add.u64 %rd18, %rd16, %rd17;    // idx

    cvt.u64.u32 %rd19, %r5;     // c
    cvt.u64.u32 %rd20, %r2;     // C

    mov.f64 %fd1, 0d0000000000000000;
    mov.f64 %fd2, 0d0000000000000000;

LOOP_START:
    setp.ge.u64 %p1, %rd18, %rd11;
    @%p1 bra LOOP_END;

    div.u64 %rd21, %rd18, %rd9;    // n
    rem.u64 %rd22, %rd18, %rd9;    // hw

    mul.lo.u64 %rd23, %rd21, %rd20; // n*C
    add.u64 %rd24, %rd23, %rd19;    // n*C+c
    mul.lo.u64 %rd25, %rd24, %rd9;  // (n*C+c)*HW
    add.u64 %rd26, %rd25, %rd22;    // offset

    shl.b64 %rd27, %rd26, 2;
    add.u64 %rd28, %rd4, %rd27;

    ld.global.f32 %f1, [%rd28];
    cvt.f64.f32 %fd3, %f1;
    add.f64 %fd1, %fd1, %fd3;
    fma.rn.f64 %fd2, %fd3, %fd3, %fd2;

    add.u64 %rd18, %rd18, %rd14;
    bra LOOP_START;

LOOP_END:
    mov.u32 %r10, smem;
    mul.lo.u32 %r11, %r8, 8;
    add.u32 %r12, %r10, %r11;      // s_sum[tid] addr

    mul.lo.u32 %r13, %r7, 8;       // threads*8
    add.u32 %r14, %r10, %r13;      // s_sumsq base
    add.u32 %r15, %r14, %r11;      // s_sumsq[tid] addr

    st.shared.f64 [%r12], %fd1;
    st.shared.f64 [%r15], %fd2;
    bar.sync 0;

    mov.u32 %r16, %r7;
    shr.u32 %r16, %r16, 1;

RED_LOOP:
    setp.eq.u32 %p2, %r16, 0;
    @%p2 bra RED_DONE;

    setp.ge.u32 %p3, %r8, %r16;
    @%p3 bra RED_SKIP;

    mul.lo.u32 %r17, %r16, 8;
    add.u32 %r18, %r12, %r17;
    ld.shared.f64 %fd4, [%r12];
    ld.shared.f64 %fd5, [%r18];
    add.f64 %fd6, %fd4, %fd5;
    st.shared.f64 [%r12], %fd6;

    add.u32 %r19, %r15, %r17;
    ld.shared.f64 %fd7, [%r15];
    ld.shared.f64 %fd8, [%r19];
    add.f64 %fd9, %fd7, %fd8;
    st.shared.f64 [%r15], %fd9;

RED_SKIP:
    bar.sync 0;
    shr.u32 %r16, %r16, 1;
    bra RED_LOOP;

RED_DONE:
    setp.ne.u32 %p4, %r8, 0;
    @%p4 bra DONE_ATOMIC;

    mul.wide.u32 %rd29, %r5, 8;
    add.u64 %rd30, %rd5, %rd29;
    ld.shared.f64 %fd10, [%r10];
    atom.global.add.f64 %fd11, [%rd30], %fd10;

    add.u64 %rd31, %rd6, %rd29;
    ld.shared.f64 %fd12, [%r14];
    atom.global.add.f64 %fd13, [%rd31], %fd12;

DONE_ATOMIC:
    ret;
}

//
// Kernel 2: finalize per-channel mean/invstd, update running stats
//
.visible .entry bn_finalize_kernel(
    .param .u64 sum,
    .param .u64 sumsq,
    .param .u64 mean_out,
    .param .u64 invstd_out,
    .param .u64 running_mean,
    .param .u64 running_var,
    .param .u32 C,
    .param .u64 count,
    .param .f32 eps,
    .param .f32 momentum,
    .param .u32 training
)
{
    .reg .pred %p<6>;
    .reg .u32 %r<10>;
    .reg .u64 %rd<25>;
    .reg .f32 %f<22>;
    .reg .f64 %fd<15>;

    ld.param.u64 %rd1, [sum];
    ld.param.u64 %rd2, [sumsq];
    ld.param.u64 %rd3, [mean_out];
    ld.param.u64 %rd4, [invstd_out];
    ld.param.u64 %rd5, [running_mean];
    ld.param.u64 %rd6, [running_var];
    ld.param.u32 %r1, [C];
    ld.param.u64 %rd7, [count];
    ld.param.f32 %f1, [eps];
    ld.param.f32 %f2, [momentum];
    ld.param.u32 %r2, [training];

    mov.u32 %r3, %ctaid.x;
    mov.u32 %r4, %ntid.x;
    mov.u32 %r5, %tid.x;
    mad.lo.s32 %r6, %r3, %r4, %r5;   // c index

    setp.ge.u32 %p1, %r6, %r1;
    @%p1 bra DONE;

    cvta.to.global.u64 %rd8, %rd1;
    cvta.to.global.u64 %rd9, %rd2;
    cvta.to.global.u64 %rd10, %rd3;
    cvta.to.global.u64 %rd11, %rd4;
    cvta.to.global.u64 %rd12, %rd5;
    cvta.to.global.u64 %rd13, %rd6;

    mul.wide.u32 %rd14, %r6, 8;   // c*8 (double arrays)
    mul.wide.u32 %rd15, %r6, 4;   // c*4 (float arrays)

    add.u64 %rd16, %rd8, %rd14;   // &sum[c]
    add.u64 %rd17, %rd9, %rd14;   // &sumsq[c]
    add.u64 %rd18, %rd10, %rd15;  // &mean_out[c]
    add.u64 %rd19, %rd11, %rd15;  // &invstd_out[c]
    add.u64 %rd20, %rd12, %rd15;  // &running_mean[c]
    add.u64 %rd21, %rd13, %rd15;  // &running_var[c]

    setp.eq.u32 %p2, %r2, 0;
    @%p2 bra EVAL_MODE;

    ld.global.f64 %fd1, [%rd16];   // sum
    ld.global.f64 %fd2, [%rd17];   // sumsq
    cvt.rn.f64.u64 %fd3, %rd7;     // count as double

    div.rn.f64 %fd4, %fd1, %fd3;   // m
    mul.f64 %fd5, %fd4, %fd4;      // m*m
    div.rn.f64 %fd6, %fd2, %fd3;   // sumsq/count
    sub.f64 %fd7, %fd6, %fd5;      // var

    setp.lt.f64 %p3, %fd7, 0d0000000000000000;
    selp.f64 %fd8, 0d0000000000000000, %fd7, %p3;  // clamped var

    cvt.rn.f32.f64 %f3, %fd4;      // mean (float)
    st.global.f32 [%rd18], %f3;

    cvt.rn.f32.f64 %f4, %fd8;      // var (float)
    add.f32 %f5, %f4, %f1;         // var+eps
    rsqrt.approx.f32 %f6, %f5;
    st.global.f32 [%rd19], %f6;

    setp.lt.u64 %p4, %rd7, 2;
    @%p4 bra SKIP_UNBIAS;

    mul.f64 %fd9, %fd8, %fd3;      // var*count
    add.u64 %rd22, %rd7, -1;
    cvt.rn.f64.u64 %fd10, %rd22;
    div.rn.f64 %fd11, %fd9, %fd10;
    cvt.rn.f32.f64 %f7, %fd11;
    bra UNBIAS_DONE;

SKIP_UNBIAS:
    mov.f32 %f7, %f4;

UNBIAS_DONE:
    ld.global.f32 %f8, [%rd20];    // running_mean
    mov.f32 %f9, 0f3F800000;       // 1.0
    sub.f32 %f10, %f9, %f2;        // 1-momentum
    mul.f32 %f11, %f10, %f8;
    fma.rn.f32 %f12, %f3, %f2, %f11;
    st.global.f32 [%rd20], %f12;

    ld.global.f32 %f13, [%rd21];   // running_var
    mul.f32 %f14, %f10, %f13;
    fma.rn.f32 %f15, %f7, %f2, %f14;
    st.global.f32 [%rd21], %f15;

    bra DONE;

EVAL_MODE:
    ld.global.f32 %f16, [%rd20];
    st.global.f32 [%rd18], %f16;
    ld.global.f32 %f17, [%rd21];
    add.f32 %f18, %f17, %f1;
    rsqrt.approx.f32 %f19, %f18;
    st.global.f32 [%rd19], %f19;

DONE:
    ret;
}

