    .param .u64 mean,
    .param .u64 invstd,
    .param .u64 weight,
    .param .u64 bias,
    .param .u32 N,
    .param .u32 C,
    .param .u32 H,
    .param .u32 W
)
{
    .reg .pred %p<6>;
    .reg .u32 %r<12>;
    .reg .u64 %rd<50>;
    .reg .f32 %f<20>;

    ld.param.u64 %rd1, [X];
    ld.param.u64 %rd2, [Y];
    ld.param.u64 %rd3, [mean];
    ld.param.u64 %rd4, [invstd];
    ld.param.u64 %rd5, [weight];
    ld.param.u64 %rd6, [bias];
    ld.param.u32 %r1, [N];
    ld.param.u32 %r2, [C];
    ld.param.u32 %r3, [H];
    ld.param.u32 %r4, [W];

    cvta.to.global.u64 %rd7, %rd1;
    cvta.to.global.u64 %rd8, %rd2;
    cvta.to.global.u64 %rd9, %rd3;
    cvta.to.global.u64 %rd10, %rd4;
    cvta.to.global.u64 %rd11, %rd5;
    cvta.to.global.u64 %rd12, %rd6;

    mov.u32 %r5, %ctaid.z;    // n
    mov.u32 %r6, %ctaid.y;    // c
    mov.u32 %r7, %ctaid.x;    // block along HW
    mov.u32 %r8, %tid.x;      // tid

    cvt.u64.u32 %rd13, %r3;   // H
    cvt.u64.u32 %rd14, %r4;   // W
    mul.lo.u64 %rd15, %rd13, %rd14;  // HW

    cvt.u64.u32 %rd16, %r2;   // C
    cvt.u64.u32 %rd17, %r5;   // n
    cvt.u64.u32 %rd18, %r6;   // c

    mul.lo.u64 %rd19, %rd17, %rd16;  // n*C
    add.u64 %rd20, %rd19, %rd18;     // n*C+c
    mul.lo.u64 %rd21, %rd20, %rd15;  // (n*C+c)*HW

    shl.b64 %rd22, %rd21, 2;         // byte offset base
    add.u64 %rd23, %rd7, %rd22;      // Xp
    add.u64 %rd24, %rd8, %rd22;      // Yp

    mul.wide.u32 %rd25, %r6, 4;      // c*4
    add.u64 %rd26, %rd9, %rd25;      // &mean[c]
    add.u64 %rd27, %rd10, %rd25;     // &invstd[c]
    add.u64 %rd28, %rd11, %rd25;     // &weight[c]
    add.u64 %rd29, %rd12, %rd25;     // &bias[c]

    ld.global.f32 %f1, [%rd26];      // m
    ld.global.f32 %f2, [%rd27];      // is
    ld.global.f32 %f3, [%rd28];      // w
    ld.global.f32 %f4, [%rd29];      // b

    mul.f32 %f5, %f2, %f3;           // scale = is*w
    mul.f32 %f6, %f1, %f5;           // m*scale
    sub.f32 %f7, %f4, %f6;           // shift = b - m*scale

    mov.u32 %r9, 1024;               // tile = threads(256)*vec(4)
    mul.lo.u32 %r10, %r7, %r9;       // base (u32)
    cvt.u64.u32 %rd30, %r10;         // base (u64)
    cvt.u64.u32 %rd31, %r8;          // tid (u64)
    add.u64 %rd32, %rd30, %rd31;     // idx0 = base + tid

    setp.ge.u64 %p1, %rd32, %rd15;
    @%p1 bra SKIP0;
    shl.b64 %rd33, %rd32, 2;
    add.u64 %rd34, %rd23, %rd33;
    add.u64 %rd35, %rd24, %rd33;
    ld.global.f32 %f8, [%rd34];
    fma.rn.f32 %f9, %f5, %f8, %f7;
    st.global.f32 [%rd35], %f9;
SKIP0:

    add.u64 %rd36, %rd32, 256;
    setp.ge.u64 %p2, %rd36, %rd15;
    @%p2 bra SKIP1;
    shl.b64 %rd37, %rd36, 2;
    add.u64 %rd38, %rd23, %rd37;
    add.u64 %rd39, %rd24, %rd37;
    ld.global.f32 %f10, [%rd38];
    fma.rn.f32 %f11, %f5, %f10, %f7;
    st.global.f32 [%rd39], %f11;
SKIP1:

    add.u64 %rd40, %rd32, 512;
    setp.ge.u64 %p3, %rd40, %rd15;
    @%p3 bra SKIP2;
    shl.b64 %rd41, %rd40, 2;
    add.u64 %rd42, %rd23, %rd41;
    add.u64 %rd43, %rd24, %rd41;
    ld.global.f32 %f12, [%rd42];
    fma.rn.f32 %f13, %f5, %f12, %f7;
    st.global.f32 [%rd43], %f13;
SKIP2:

    add.u64 %rd44, %rd32, 768;
    setp.ge.u64 %p4, %rd44, %rd15;
    @%p4 bra SKIP3;
    shl.b64 %rd45, %rd44, 2;
    add.u64 %rd46, %rd23, %rd45;
    add.u64 %rd47, %rd24, %rd45;
    ld.global.f32 %f14, [%rd46];
    fma.rn.f32 %f15, %f5, %f14, %f7;
    st.global.f32 [%rd47], %f15;
