"""

_KERNEL_NAMES = ("bn_reduce_kernel", "bn_finalize_kernel", "bn_apply_kernel")

_module = None


def _get_module():
    global _module
    if _module is None:
        _module = PtxModule(PTX_SOURCE)
    return _module


def validate_generated_code():
    """Ensure that all expected kernel entries exist in the compiled module."""
    module = _get_module()
    for name in _KERNEL_NAMES:
        module.function(name)
    return True


class ModelNew(nn.Module):
    """
    PTX implementation of BatchNorm2d (training + eval) using PtxModule.
    """
    def __init__(self, num_features: int):
        super(ModelNew, self).__init__()
        self.num_features = num_features
        self.eps = 1e-5
        self.momentum = 0.1

        self.weight = nn.Parameter(torch.ones(num_features))
        self.bias = nn.Parameter(torch.zeros(num_features))

        self.register_buffer("running_mean", torch.zeros(num_features))
        self.register_buffer("running_var", torch.ones(num_features))
        self.register_buffer("num_batches_tracked", torch.tensor(0, dtype=torch.long))

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda and x.dtype == torch.float32 and x.dim() == 4

        if self.training:
            self.num_batches_tracked += 1

        module = _get_module()

        x_c = x.contiguous()
        weight_c = self.weight.contiguous()
        bias_c = self.bias.contiguous()
        running_mean_c = self.running_mean.contiguous()
        running_var_c = self.running_var.contiguous()

        N, C, H, W = x_c.shape
        y = torch.empty_like(x_c)

        sum_buf = torch.zeros(C, dtype=torch.float64, device=x_c.device)
        sumsq_buf = torch.zeros(C, dtype=torch.float64, device=x_c.device)
        mean_buf = torch.empty(C, dtype=torch.float32, device=x_c.device)
        invstd_buf = torch.empty(C, dtype=torch.float32, device=x_c.device)

        stream = torch.cuda.current_stream().cuda_stream
        count = N * H * W

        if self.training:
            threads = 256
            HW = H * W
            total = N * HW
            blocks_per_channel = (total + threads - 1) // threads
            blocks_per_channel = max(1, min(blocks_per_channel, 4096))
            shmem_bytes = 2 * threads * 8  # two double arrays

            module.launch(
                "bn_reduce_kernel",
                grid=(blocks_per_channel, C, 1),
                block=(threads, 1, 1),
                shared_mem=shmem_bytes,
                stream=stream,
                args=[
                    u64(x_c.data_ptr()),
                    u64(sum_buf.data_ptr()),
                    u64(sumsq_buf.data_ptr()),
                    u32(N), u32(C), u32(H), u32(W),
                ],
            )

        {
            threads2 = 128
            blocks2 = (C + threads2 - 1) // threads2
            module.launch(
                "bn_finalize_kernel",
                grid=(blocks2, 1, 1),
                block=(threads2, 1, 1),
                shared_mem=0,
                stream=stream,
                args=[
                    u64(sum_buf.data_ptr()),
                    u64(sumsq_buf.data_ptr()),
                    u64(mean_buf.data_ptr()),
                    u64(invstd_buf.data_ptr()),
                    u64(running_mean_c.data_ptr()),
                    u64(running_var_c.data_ptr()),
                    u32(C),
                    u64(count),
                    f32(self.eps),
                    f32(self.momentum),
                    u32(1 if self.training else 0),
                ],
            )
        }

        {
            threads3 = 256
            vec = 4
            HW = H * W
            tile = threads3 * vec
            gx = (HW + tile - 1) // tile
            module.launch(
                "bn_apply_kernel",
                grid=(gx, C, N),
                block=(threads3, 1, 1),
                shared_mem=0,
                stream=stream,
                args=[
                    u64(x_c.data_ptr()),
                    u64(y.data_ptr()),
                    u64(mean_buf.data_ptr()),
                    u64(invstd_buf.data_ptr()),
                    u64(weight_c.data_ptr()),
                    u64(bias_c.data_ptr()),
                    u32(N), u32(C), u32(H), u32(W),
                ],
            )
        }

        self.running_mean.copy_(running_mean_c)
        self.running_var.copy_(running_var_c)

        return y
